import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.CvydjLy7.js";const c=JSON.parse('{"title":"二、数据源：从自动配置到连接池","description":"","frontmatter":{"title":"二、数据源：从自动配置到连接池"},"headers":[{"level":3,"title":"2.1 嵌入式数据库是自动配好的","slug":"_2-1-嵌入式数据库是自动配好的","link":"#_2-1-嵌入式数据库是自动配好的","children":[]},{"level":3,"title":"2.2 连接生产数据库","slug":"_2-2-连接生产数据库","link":"#_2-2-连接生产数据库","children":[]},{"level":3,"title":"2.3 连接池是按固定顺序挑的","slug":"_2-3-连接池是按固定顺序挑的","link":"#_2-3-连接池是按固定顺序挑的","children":[]},{"level":3,"title":"2.4 HikariCP 实际生效的参数","slug":"_2-4-hikaricp-实际生效的参数","link":"#_2-4-hikaricp-实际生效的参数","children":[]},{"level":3,"title":"2.5 该动哪几个参数","slug":"_2-5-该动哪几个参数","link":"#_2-5-该动哪几个参数","children":[]},{"level":3,"title":"2.6 延迟获取连接","slug":"_2-6-延迟获取连接","link":"#_2-6-延迟获取连接","children":[]},{"level":3,"title":"2.7 JNDI 数据源","slug":"_2-7-jndi-数据源","link":"#_2-7-jndi-数据源","children":[]}],"relativePath":"ch06/02.md","filePath":"ch06/02.md","lastUpdated":1789497795000}'),e={name:"ch06/02.md"};function l(p,s,d,h,r,o){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="二、数据源-从自动配置到连接池" tabindex="-1">二、数据源：从自动配置到连接池 <a class="header-anchor" href="#二、数据源-从自动配置到连接池" aria-label="Permalink to &quot;二、数据源：从自动配置到连接池&quot;">​</a></h1><h3 id="_2-1-嵌入式数据库是自动配好的" tabindex="-1">2.1 嵌入式数据库是自动配好的 <a class="header-anchor" href="#_2-1-嵌入式数据库是自动配好的" aria-label="Permalink to &quot;2.1 嵌入式数据库是自动配好的&quot;">​</a></h3><p>Spring Boot 的默认行为是：<strong>类路径上检测到嵌入式数据库驱动，就自动配一个内存数据源</strong>，不需要写任何 <code>url</code>。官方明确支持 H2、HSQL，Derby 已标记为废弃（<code>datasource-embedded-database-connection</code> 相关文档里标了 deprecated）。</p><p>本项目的 <code>application.yml</code> 只写了最必要的东西：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  datasource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jdbc:h2:mem:activity;DB_CLOSE_DELAY=-1;MODE=MySQL</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    driver-class-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">org.h2.Driver</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sa</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>三个参数里有两个是为了教学方便：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>DB_CLOSE_DELAY=-1</code></td><td>最后一个连接关闭后不销毁数据库。不加的话，连接池空闲回收时数据库会被清空</td></tr><tr><td><code>MODE=MySQL</code></td><td>让 H2 按 MySQL 的语法规则解析，SQL 写法可以平移</td></tr></tbody></table><p>有几个容易忽略的点：</p><ul><li><strong>驱动类名通常可以省略</strong>。Spring Boot 能从 <code>url</code> 的 <code>jdbc:h2:</code> 前缀推断出驱动，写出来只是为了让初学者看清对应关系。</li><li><strong>多个嵌入式数据库并存时要显式指定</strong>。同时引了 H2 和 HSQL 时，用 <code>spring.datasource.embedded-database-connection=h2</code> 选一个；设为 <code>none</code> 则关闭嵌入式数据源自动配置。</li><li><strong>测试时希望每个上下文用独立库</strong>，加 <code>spring.datasource.generate-unique-name=true</code>，否则多个测试类共用同一个内存库，数据会互相干扰。</li></ul><h3 id="_2-2-连接生产数据库" tabindex="-1">2.2 连接生产数据库 <a class="header-anchor" href="#_2-2-连接生产数据库" aria-label="Permalink to &quot;2.2 连接生产数据库&quot;">​</a></h3><p>换到 MySQL 或 PostgreSQL 时，改动只有依赖和三项配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  datasource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jdbc:mysql://localhost:3306/activity?useSSL=false&amp;serverTimezone=Asia/Shanghai</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">activity</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${DB_PASSWORD}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    driver-class-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">com.mysql.cj.jdbc.Driver</span></span></code></pre></div><p>密码不要写在 yml 里，用环境变量占位（第 3 篇讲过外部化配置的优先级）。</p><h3 id="_2-3-连接池是按固定顺序挑的" tabindex="-1">2.3 连接池是按固定顺序挑的 <a class="header-anchor" href="#_2-3-连接池是按固定顺序挑的" aria-label="Permalink to &quot;2.3 连接池是按固定顺序挑的&quot;">​</a></h3><p>官方文档给出的选择算法是一个优先级队列，命中即用：</p><table tabindex="0"><thead><tr><th>顺序</th><th>实现</th><th>触发条件</th></tr></thead><tbody><tr><td>1</td><td><strong>HikariCP</strong></td><td>类路径上存在，就总是选它</td></tr><tr><td>2</td><td>Tomcat JDBC Pool</td><td>没有 HikariCP，但有 <code>tomcat-jdbc</code></td></tr><tr><td>3</td><td>Commons DBCP2</td><td>没有前两个，但有 <code>commons-dbcp2</code></td></tr><tr><td>4</td><td>Oracle UCP</td><td>以上都没有，但有 <code>ucp</code></td></tr></tbody></table><p>引入 <code>spring-boot-starter-jdbc</code> 或 <code>spring-boot-starter-data-jpa</code> 就会带上 HikariCP，所以实际上绝大多数项目用的都是它。想绕开这个顺序、强行指定，用 <code>spring.datasource.type</code> 写全限定类名。</p><p><strong>注意 <code>spring-boot-starter-web</code> 不含 JDBC</strong>。只引 Web 依赖的项目不会有连接池，这一点在排查“为什么 <code>DataSource</code> 注入不进来”时经常是根因。</p><h3 id="_2-4-hikaricp-实际生效的参数" tabindex="-1">2.4 HikariCP 实际生效的参数 <a class="header-anchor" href="#_2-4-hikaricp-实际生效的参数" aria-label="Permalink to &quot;2.4 HikariCP 实际生效的参数&quot;">​</a></h3><p>网上讲连接池调参的文章常把默认值写得含糊。下面这份是实测读出来的——在案例工程里注入 <code>HikariDataSource</code> 后直接调用它的 getter（HikariCP 7.0.2）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>池名 poolName                = HikariPool-1</span></span>
<span class="line"><span>jdbcUrl                      = jdbc:h2:mem:activity;DB_CLOSE_DELAY=-1;MODE=MySQL</span></span>
<span class="line"><span>maximumPoolSize              = 10</span></span>
<span class="line"><span>minimumIdle                  = 10</span></span>
<span class="line"><span>connectionTimeout(ms)        = 30000</span></span>
<span class="line"><span>idleTimeout(ms)              = 600000</span></span>
<span class="line"><span>maxLifetime(ms)              = 1800000</span></span>
<span class="line"><span>leakDetectionThreshold(ms)   = 0</span></span>
<span class="line"><span>validationTimeout(ms)        = 5000</span></span>
<span class="line"><span>keepaliveTime(ms)            = 120000</span></span>
<span class="line"><span>autoCommit                   = true</span></span></code></pre></div><p>启动日志里也能看到它的生命周期：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HikariDataSource : HikariPool-1 - Starting...</span></span>
<span class="line"><span>HikariPool       : HikariPool-1 - Added connection conn0: url=jdbc:h2:mem:activity user=SA</span></span>
<span class="line"><span>HikariDataSource : HikariPool-1 - Start completed.</span></span></code></pre></div><h3 id="_2-5-该动哪几个参数" tabindex="-1">2.5 该动哪几个参数 <a class="header-anchor" href="#_2-5-该动哪几个参数" aria-label="Permalink to &quot;2.5 该动哪几个参数&quot;">​</a></h3><p>默认值对教学项目和中小系统足够用。真正需要调的是下面这几个：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>什么时候要改</th></tr></thead><tbody><tr><td><code>maximum-pool-size</code></td><td>10</td><td>并发高且 SQL 快时上调；<strong>不是越大越好</strong>，池子超过数据库的连接上限反而会让请求排队</td></tr><tr><td><code>minimum-idle</code></td><td>与最大值相同</td><td>想让闲置时释放连接（省数据库内存）就调小，代价是突发流量要等新建连接</td></tr><tr><td><code>connection-timeout</code></td><td>30000</td><td>拿不到连接时的等待上限。<strong>不要设成 0</strong>（无限等待），那会让线程永久挂住</td></tr><tr><td><code>max-lifetime</code></td><td>1800000</td><td>必须<strong>小于</strong>数据库侧的连接空闲超时（MySQL 默认 8 小时，但中间件常设更短），否则会拿到已被服务端断开的连接</td></tr><tr><td><code>leak-detection-threshold</code></td><td>0（关闭）</td><td>排查“连接不够用”时临时设为 10000（10 秒），日志会打印出借出超过阈值却没归还的调用栈</td></tr><tr><td><code>keepalive-time</code></td><td>120000</td><td>走防火墙或云数据库时保留，用于探活</td></tr></tbody></table><p>对应到 yml 的写法：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  datasource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    hikari</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      maximum-pool-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      minimum-idle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      connection-timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      max-lifetime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1200000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      leak-detection-threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pool-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">activity-server-pool</span></span></code></pre></div><blockquote><p><strong>连接池耗尽不是加池子能解决的</strong></p><p>出现“连接池满了”时，先分清是 SQL 慢占着连接不放，还是代码借了连接没还。前者要优化 SQL 或加索引，后者要看有没有在事务里调用外部 HTTP 接口——那类操作会把数据库连接白白占住几百毫秒到几秒。把池子从 10 加到 100，只是把问题推后。</p></blockquote><h3 id="_2-6-延迟获取连接" tabindex="-1">2.6 延迟获取连接 <a class="header-anchor" href="#_2-6-延迟获取连接" aria-label="Permalink to &quot;2.6 延迟获取连接&quot;">​</a></h3><p>Spring Boot 4 新增了一个开关：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  datasource</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    connection-fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lazy</span></span></code></pre></div><p>默认情况下，一次事务开始就立刻从池里取一个连接。设为 <code>lazy</code> 后，直到真正执行第一条 SQL 才取连接。好处是“开了事务但没发 SQL”的场景（比如只做校验、构造响应的只读事务）不再占用连接。</p><p>代价是事务的隔离性边界会变得微妙——连接是延迟绑定的，事务开始到取连接之间发生的事不受事务保护。<strong>只在确认业务逻辑不需要这个边界时使用</strong>。</p><h3 id="_2-7-jndi-数据源" tabindex="-1">2.7 JNDI 数据源 <a class="header-anchor" href="#_2-7-jndi-数据源" aria-label="Permalink to &quot;2.7 JNDI 数据源&quot;">​</a></h3><p>部署到传统应用服务器（Tomcat、WebLogic）且连接池由容器管理时，用 <code>spring.datasource.jndi-name</code> 替代 url / username / password 三项。容器化的 Spring Boot 应用基本用不到。</p>`,36)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
